def build(points, depth=0, k=2):
    if not points:
        return None
    axis = depth % k  # 레벨마다 축 순환
    points = sorted(points, key=lambda p: p[axis])
    m = len(points) // 2  # 중앙값 분할
    return Node(points[m], axis,
                build(points[:m], depth + 1, k),
                build(points[m + 1:], depth + 1, k))

def nearest(node, q, best=None):
    if node is None:
        return best
    if best is None or dist(q, node.point) < dist(q, best):
        best = node.point
    diff = q[node.axis] - node.point[node.axis]
    if diff < 0:
        near, far = node.left, node.right
    else:
        near, far = node.right, node.left
    best = nearest(near, q, best)
    if abs(diff) < dist(q, best):  # 분할면 너머 확인
        best = nearest(far, q, best)
    return best
